<!doctype html><html><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>Player</title><link rel='stylesheet' href='/assets/css/ui.css'><link rel='stylesheet' href='/assets/css/components.css'><link rel='stylesheet' href='https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css'></head><body><script src='/assets/js/ui.js'></script><script>
UX.shell('',`<div id='wrap' class='glass-card'><div class='skeleton' style='height:120px'></div></div>`);
(async()=>{const id=Number(location.pathname.split('/').pop()||0);try{const p=await UX.api('/api/player/profile-detail?id='+id);wrap.innerHTML=`<div class='hero'><h2>${p.username}</h2><span class='badge'>Lv ${p.level}</span></div><div class='grid cols-3'><div class='glass-card'><div class='sub'>Coins</div><div class='kpi'>${UX.fmt(p.coins)}</div></div><div class='glass-card'><div class='sub'>Gold</div><div class='kpi'>${UX.fmt(p.gold)}</div></div><div class='glass-card'><div class='sub'>Region</div><div class='kpi'>${p.region_name||'-'}</div></div></div><div class='glass-card' style='margin-top:10px'><b>Nation:</b> ${p.nation_name||'-'}<br><b>Stats:</b> STR ${p.strength} • EDU ${p.education} • END ${p.endurance}</div>`;}catch(e){wrap.innerHTML=`<div class='glass-card'>${e.message}</div>`;}})();
</script></body></html>
